def main() -> int:
    root = Path.cwd()
    dependency = root / "qseries_v2" / "oracle_intelligence" / "analytics" / "oracle_market_usefulness_scoring_engine.py"
    feature_dependency = root / "qseries_v2" / "oracle_intelligence" / "analytics" / "oracle_market_feature_extraction_engine.py"
    if not dependency.exists() or not feature_dependency.exists():
        raise SystemExit("[FAIL] OIA-004/OIA-005 production modules are missing. Install and pass them first.")
    usefulness_text = dependency.read_text(encoding="utf-8")
    feature_text = feature_dependency.read_text(encoding="utf-8")
    required_usefulness = ('SCHEMA_VERSION = "OIA-005"', 'class OracleMarketUsefulnessScoringEngine:', 'class OracleMarketUsefulnessRecord:', 'class OracleMarketUsefulnessReport:', 'usefulness_hash')
    required_features = ('SCHEMA_VERSION = "OIA-004"', 'class OracleCanonicalMarketFeatureRecord:', 'directional_change_ratio', 'movement_efficiency_ratio')
    missing = [token for token in required_usefulness if token not in usefulness_text] + [token for token in required_features if token not in feature_text]
    if missing:
        raise SystemExit(f"[FAIL] Actual OIA-004/OIA-005 contract mismatch: {missing}")
    print("========================================")
    print(" OIA-006 INSTALLER")
    print(" ORACLE OPPORTUNITY CANDIDATE GENERATOR")
    print(" READ-ONLY RESEARCH HYPOTHESIS LAYER")
    print("========================================")
    print("[OK] Actual OIA-004 feature and OIA-005 usefulness contracts verified")
    package = root / "qseries_v2" / "oracle_intelligence" / "analytics"
    package.mkdir(parents=True, exist_ok=True)
    targets = (
        (package / "oracle_opportunity_candidate_generator.py", MODULE),
        (package / "__init__.py", INIT),
        (root / "test_oia_006_oracle_opportunity_candidate_generator.py", TEST),
    )
    for path, content in targets:
        path.write_text(content, encoding="utf-8", newline="\n")
        print(f"[OK] FULL REPLACEMENT: {path}")
    for path, content in targets:
        ast.parse(content, filename=str(path))
    print("[OK] OIA-006 production, package, and test syntax verified")
    completed = subprocess.run([sys.executable, str(root / "test_oia_006_oracle_opportunity_candidate_generator.py")], cwd=root)
    if completed.returncode != 0:
        raise SystemExit(completed.returncode)
    print("[OK] OIA-006 test executed successfully")
    print("[DONE] OIA-006 Oracle Opportunity Candidate Generator installed")
    print()
    print("Generate live research candidates with:")
    print("python -m qseries_v2.oracle_intelligence.analytics.oracle_opportunity_candidate_generator")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
